-- Postgres dialect of schema/0001_tenancy.sql (Phase 0 PR14).
--
-- Kept in parity with the SQLite DDL by TestSchemaParity_SQLiteAndPostgres
-- (same tables, same columns, same NOT NULL-ness). Differences, all deliberate:
--
--   - INTEGER PRIMARY KEY becomes BIGINT GENERATED BY DEFAULT AS IDENTITY.
--   - Foreign keys between tenant tables are COMPOSITE (tenant_id, x_id) ->
--     (tenant_id, id) against a UNIQUE (tenant_id, id) on the parent, so the
--     database itself refuses a reference into another tenant (design §7.3).
--     They replace the SQLite guard triggers. References that are not foreign
--     keys keep a trigger: graph node keys such as 'account:12', and "soft"
--     references to rows that may be gone (access_requests.edge_id,
--     review_items.edge_id, hris_events.identity_id,
--     readiness_item_states.check_run_id).
--   - Tables that SQLite orders by its implicit rowid get an explicit
--     `rowid` identity column.
--   - Timestamps stay TEXT in the store's sortable UTC form, like SQLite.
--
-- tenant_id stays TEXT (not uuid): row-level security compares it with the
-- app.tenant_id setting as text (rls.sql), so an unset or empty setting
-- matches nothing and no cast can fail.
--
-- Append-only and guard triggers are plpgsql; they raise messages the store
-- recognises ('cross-tenant reference', 'append-only', 'immutable').

-- +goose Up

-- +goose StatementBegin
CREATE OR REPLACE FUNCTION tessera_abort() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
	RAISE EXCEPTION '%', TG_ARGV[0] USING ERRCODE = 'integrity_constraint_violation';
END
$fn$;
-- +goose StatementEnd

-- GLOBAL
CREATE TABLE tenants (
	id                TEXT PRIMARY KEY,
	slug              TEXT NOT NULL UNIQUE CHECK (length(slug) BETWEEN 3 AND 40 AND slug !~ '[^a-z0-9_-]'),
	name              TEXT NOT NULL,
	status            TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','recovery')),
	cell              TEXT NOT NULL DEFAULT 'local',
	min_admins        BIGINT NOT NULL DEFAULT 2 CHECK (min_admins >= 2),
	settings          TEXT NOT NULL DEFAULT '{}',
	security_contacts TEXT NOT NULL DEFAULT '[]',
	created_at        TEXT NOT NULL
);

CREATE TABLE identities (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	tenant_id TEXT NOT NULL REFERENCES tenants (id),
	external_id TEXT NOT NULL, name TEXT NOT NULL, email TEXT,
	type TEXT NOT NULL, department TEXT, title TEXT, status TEXT NOT NULL, manager_id BIGINT,
	owner_id BIGINT, source TEXT, description TEXT, hired_at TEXT, terminated_at TEXT,
	created_at TEXT NOT NULL,
	UNIQUE (tenant_id, id),
	FOREIGN KEY (tenant_id, manager_id) REFERENCES identities (tenant_id, id),
	FOREIGN KEY (tenant_id, owner_id) REFERENCES identities (tenant_id, id));
CREATE UNIQUE INDEX ux_identities_tenant_external_id ON identities (tenant_id, external_id);
CREATE INDEX ix_identities_tenant_email ON identities (tenant_id, email);
CREATE INDEX ix_identities_tenant_type ON identities (tenant_id, type);
CREATE INDEX ix_identities_tenant_owner ON identities (tenant_id, owner_id);
CREATE INDEX ix_identities_tenant_manager ON identities (tenant_id, manager_id);

CREATE TABLE accounts (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	tenant_id TEXT NOT NULL REFERENCES tenants (id),
	system TEXT NOT NULL, external_id TEXT NOT NULL, identity_id BIGINT,
	username TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT, last_login_at TEXT,
	UNIQUE (tenant_id, id),
	UNIQUE (tenant_id, system, external_id),
	FOREIGN KEY (tenant_id, identity_id) REFERENCES identities (tenant_id, id));
CREATE INDEX ix_accounts_tenant_system ON accounts (tenant_id, system);
CREATE INDEX ix_accounts_tenant_identity ON accounts (tenant_id, identity_id);

CREATE TABLE groups (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	tenant_id TEXT NOT NULL REFERENCES tenants (id),
	system TEXT NOT NULL, external_id TEXT NOT NULL, name TEXT NOT NULL,
	kind TEXT NOT NULL, privileged BIGINT NOT NULL, requestable BIGINT NOT NULL, description TEXT,
	UNIQUE (tenant_id, id),
	UNIQUE (tenant_id, system, external_id));
CREATE INDEX ix_groups_tenant_system ON groups (tenant_id, system);

CREATE TABLE resources (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	tenant_id TEXT NOT NULL REFERENCES tenants (id),
	system TEXT NOT NULL, external_id TEXT NOT NULL, name TEXT NOT NULL,
	kind TEXT NOT NULL, environment TEXT, tags TEXT NOT NULL,
	UNIQUE (tenant_id, id),
	UNIQUE (tenant_id, system, external_id));
CREATE INDEX ix_resources_tenant_system ON resources (tenant_id, system);

CREATE TABLE permissions (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	tenant_id TEXT NOT NULL REFERENCES tenants (id),
	system TEXT NOT NULL, external_id TEXT NOT NULL, action TEXT NOT NULL,
	resource_id BIGINT NOT NULL, privileged BIGINT NOT NULL,
	UNIQUE (tenant_id, id),
	UNIQUE (tenant_id, system, external_id),
	FOREIGN KEY (tenant_id, resource_id) REFERENCES resources (tenant_id, id));
CREATE INDEX ix_permissions_tenant_system ON permissions (tenant_id, system);
CREATE INDEX ix_permissions_tenant_action ON permissions (tenant_id, action);

CREATE TABLE grant_edges (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	tenant_id TEXT NOT NULL REFERENCES tenants (id),
	src TEXT NOT NULL, dst TEXT NOT NULL, relation TEXT NOT NULL,
	source TEXT NOT NULL, expires_at TEXT, created_at TEXT NOT NULL,
	UNIQUE (tenant_id, id),
	UNIQUE (tenant_id, src, dst));
CREATE INDEX ix_grant_edges_tenant_src ON grant_edges (tenant_id, src);
CREATE INDEX ix_grant_edges_tenant_dst ON grant_edges (tenant_id, dst);

CREATE TABLE secrets (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	tenant_id TEXT NOT NULL REFERENCES tenants (id),
	system TEXT NOT NULL, external_id TEXT NOT NULL, account_id BIGINT NOT NULL,
	kind TEXT NOT NULL, name TEXT NOT NULL, created_at TEXT NOT NULL, last_rotated_at TEXT,
	last_used_at TEXT, status TEXT NOT NULL,
	UNIQUE (tenant_id, system, external_id),
	FOREIGN KEY (tenant_id, account_id) REFERENCES accounts (tenant_id, id));
CREATE INDEX ix_secrets_tenant_account ON secrets (tenant_id, account_id);

CREATE TABLE agent_delegations (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	tenant_id TEXT NOT NULL REFERENCES tenants (id),
	agent_id BIGINT NOT NULL, principal_id BIGINT NOT NULL, scopes TEXT NOT NULL,
	created_at TEXT NOT NULL, expires_at TEXT,
	FOREIGN KEY (tenant_id, agent_id) REFERENCES identities (tenant_id, id),
	FOREIGN KEY (tenant_id, principal_id) REFERENCES identities (tenant_id, id));
CREATE INDEX ix_agent_delegations_tenant ON agent_delegations (tenant_id);

CREATE TABLE usage_events (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	tenant_id TEXT NOT NULL REFERENCES tenants (id),
	identity_id BIGINT NOT NULL, account_id BIGINT, permission_id BIGINT NOT NULL,
	day TEXT NOT NULL, count BIGINT NOT NULL,
	FOREIGN KEY (tenant_id, identity_id) REFERENCES identities (tenant_id, id),
	FOREIGN KEY (tenant_id, account_id) REFERENCES accounts (tenant_id, id),
	FOREIGN KEY (tenant_id, permission_id) REFERENCES permissions (tenant_id, id));
CREATE INDEX ix_usage_events_tenant_day ON usage_events (tenant_id, day);
CREATE INDEX ix_usage_events_tenant_cover ON usage_events (tenant_id, identity_id, permission_id, day, count);

CREATE TABLE access_requests (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	tenant_id TEXT NOT NULL REFERENCES tenants (id),
	identity_id BIGINT NOT NULL, account_id BIGINT NOT NULL, group_id BIGINT NOT NULL,
	justification TEXT NOT NULL, duration_hours DOUBLE PRECISION NOT NULL, status TEXT NOT NULL, requested_at TEXT NOT NULL,
	decided_at TEXT, decided_by TEXT, expires_at TEXT, edge_id BIGINT,
	-- platform users (0005_auth.sql); decided_by stays as the display string
	requested_by_user_id TEXT, decided_by_user_id TEXT,
	FOREIGN KEY (tenant_id, identity_id) REFERENCES identities (tenant_id, id),
	FOREIGN KEY (tenant_id, account_id) REFERENCES accounts (tenant_id, id),
	FOREIGN KEY (tenant_id, group_id) REFERENCES groups (tenant_id, id));
-- edge_id is deliberately not a foreign key: a JIT edge expires and is deleted
-- while the request that created it stays as history. It keeps a cross-tenant
-- guard trigger instead (tessera_guard_soft_ref below).
CREATE INDEX ix_access_requests_tenant_status ON access_requests (tenant_id, status);

CREATE TABLE review_campaigns (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	tenant_id TEXT NOT NULL REFERENCES tenants (id),
	name TEXT NOT NULL, created_at TEXT NOT NULL, status TEXT NOT NULL,
	unused_days BIGINT NOT NULL, total_grants BIGINT NOT NULL, auto_certified BIGINT NOT NULL,
	UNIQUE (tenant_id, id));
CREATE INDEX ix_review_campaigns_tenant ON review_campaigns (tenant_id);

CREATE TABLE review_items (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	tenant_id TEXT NOT NULL REFERENCES tenants (id),
	campaign_id BIGINT NOT NULL, identity_id BIGINT NOT NULL, edge_id BIGINT,
	edge_src TEXT NOT NULL, edge_dst TEXT NOT NULL, grant_label TEXT NOT NULL, reasons TEXT NOT NULL,
	context TEXT NOT NULL, reviewer_id BIGINT, decision TEXT, comment TEXT, decided_at TEXT,
	decided_by_user_id TEXT,
	FOREIGN KEY (tenant_id, campaign_id) REFERENCES review_campaigns (tenant_id, id),
	FOREIGN KEY (tenant_id, identity_id) REFERENCES identities (tenant_id, id),
	FOREIGN KEY (tenant_id, reviewer_id) REFERENCES identities (tenant_id, id));
CREATE INDEX ix_review_items_tenant_campaign ON review_items (tenant_id, campaign_id);

CREATE TABLE hris_events (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	tenant_id TEXT NOT NULL REFERENCES tenants (id),
	external_id TEXT NOT NULL, type TEXT NOT NULL, identity_id BIGINT,
	payload TEXT NOT NULL, effective_at TEXT NOT NULL, status TEXT NOT NULL, executed_at TEXT,
	executed_by_user_id TEXT,
	UNIQUE (tenant_id, external_id));
-- identity_id is deliberately not a foreign key: an event row may name an
-- identity that no longer exists (UAT #133); it keeps a guard trigger instead.

-- Cross-tenant guard for graph node keys ('identity:12', 'account:7', ...).
-- They are text, not foreign keys, so the composite-FK mechanism cannot cover
-- them. The function is SECURITY DEFINER so it can see other tenants' rows
-- under row-level security: the migration role must be a superuser or have
-- BYPASSRLS (README, "Postgres"). Without that it degrades to "the row is not
-- visible", which row-level security already guarantees.
-- +goose StatementBegin
CREATE OR REPLACE FUNCTION tessera_node_key_crosses(node_key text, tid text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $fn$
DECLARE
	kind text;
	num bigint;
BEGIN
	IF node_key IS NULL OR position(':' IN node_key) = 0 THEN
		RETURN false;
	END IF;
	kind := split_part(node_key, ':', 1);
	num := substring(substr(node_key, position(':' IN node_key) + 1) FROM '^[0-9]+')::bigint;
	IF num IS NULL THEN
		RETURN false;
	END IF;
	RETURN CASE kind
		WHEN 'identity' THEN EXISTS (SELECT 1 FROM identities p WHERE p.id = num AND p.tenant_id <> tid)
		WHEN 'account' THEN EXISTS (SELECT 1 FROM accounts p WHERE p.id = num AND p.tenant_id <> tid)
		WHEN 'group' THEN EXISTS (SELECT 1 FROM groups p WHERE p.id = num AND p.tenant_id <> tid)
		WHEN 'perm' THEN EXISTS (SELECT 1 FROM permissions p WHERE p.id = num AND p.tenant_id <> tid)
		WHEN 'resource' THEN EXISTS (SELECT 1 FROM resources p WHERE p.id = num AND p.tenant_id <> tid)
		ELSE false END;
END
$fn$;
-- +goose StatementEnd

-- +goose StatementBegin
CREATE OR REPLACE FUNCTION tessera_guard_grant_edges() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
	IF tessera_node_key_crosses(NEW.src, NEW.tenant_id) OR tessera_node_key_crosses(NEW.dst, NEW.tenant_id) THEN
		RAISE EXCEPTION 'cross-tenant reference: grant_edges' USING ERRCODE = 'integrity_constraint_violation';
	END IF;
	RETURN NEW;
END
$fn$;
-- +goose StatementEnd

-- +goose StatementBegin
CREATE OR REPLACE FUNCTION tessera_guard_review_items() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
	IF tessera_node_key_crosses(NEW.edge_src, NEW.tenant_id) OR tessera_node_key_crosses(NEW.edge_dst, NEW.tenant_id) THEN
		RAISE EXCEPTION 'cross-tenant reference: review_items' USING ERRCODE = 'integrity_constraint_violation';
	END IF;
	RETURN NEW;
END
$fn$;
-- +goose StatementEnd

-- Soft references: a column that names a row of another table without being a
-- foreign key because the row may legitimately be gone (a JIT edge that
-- expired, an event for a deleted identity). The trigger refuses a row that
-- exists in ANOTHER tenant and tolerates one that does not exist, like the
-- SQLite guard triggers. Arguments: parent table, column, id type (bigint or
-- text). SECURITY DEFINER for the same reason as tessera_node_key_crosses.
-- +goose StatementBegin
CREATE OR REPLACE FUNCTION tessera_guard_soft_ref() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $fn$
DECLARE
	val text := to_jsonb(NEW) ->> TG_ARGV[1];
	crosses boolean;
BEGIN
	IF val IS NULL THEN
		RETURN NEW;
	END IF;
	EXECUTE format('SELECT EXISTS (SELECT 1 FROM %I p WHERE p.id = $1::%s AND p.tenant_id <> $2)', TG_ARGV[0], TG_ARGV[2])
		INTO crosses USING val, NEW.tenant_id;
	IF crosses THEN
		RAISE EXCEPTION 'cross-tenant reference: %', TG_TABLE_NAME USING ERRCODE = 'integrity_constraint_violation';
	END IF;
	RETURN NEW;
END
$fn$;
-- +goose StatementEnd

CREATE TRIGGER tg_access_requests_edge_xtenant BEFORE INSERT OR UPDATE OF tenant_id, edge_id ON access_requests
	FOR EACH ROW EXECUTE FUNCTION tessera_guard_soft_ref('grant_edges', 'edge_id', 'bigint');
CREATE TRIGGER tg_review_items_edge_xtenant BEFORE INSERT OR UPDATE OF tenant_id, edge_id ON review_items
	FOR EACH ROW EXECUTE FUNCTION tessera_guard_soft_ref('grant_edges', 'edge_id', 'bigint');
CREATE TRIGGER tg_hris_events_identity_xtenant BEFORE INSERT OR UPDATE OF tenant_id, identity_id ON hris_events
	FOR EACH ROW EXECUTE FUNCTION tessera_guard_soft_ref('identities', 'identity_id', 'bigint');

CREATE TRIGGER tg_grant_edges_xtenant BEFORE INSERT OR UPDATE OF tenant_id, src, dst ON grant_edges
	FOR EACH ROW EXECUTE FUNCTION tessera_guard_grant_edges();
CREATE TRIGGER tg_review_items_xtenant BEFORE INSERT OR UPDATE OF tenant_id, edge_src, edge_dst ON review_items
	FOR EACH ROW EXECUTE FUNCTION tessera_guard_review_items();
